// Generated by grafana-k6 on 2026-08-19T06:21:12Z
/**
 * TOEFL Prep — quiz flow load test (closed model, ramping VUs).
 *
 * Each VU uses a dedicated account studentN@toefl.dev (N = __VU) because a
 * user may hold only one active attempt per exam template (FR-4.10). Create
 * the users first:
 *
 *   DATABASE_URL=... go run ./cmd/genusers -n 40
 *
 * Each iteration performs the full student path: login -> exams -> start ->
 * answer all items -> submit -> review -> dashboard. sleep() models think
 * time. Thresholds gate CI on p95/p99 latency and error rate.
 *
 * Run:
 *   k6 run k6/scripts/load-quiz-flow.js
 */
import http from 'k6/http';
import { check, sleep, fail } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://localhost:8080';
const API = `${BASE_URL}/api/v1`;
const PASSWORD = __ENV.PASSWORD || 'student1234';
const EXAM_ID = Number(__ENV.EXAM_ID || 1);

// 40 users must exist (see cmd/genusers). VUs beyond that share users and
// will hit the one-active-attempt conflict; keep vus <= 40.
const EMAIL = () => `student${__VU}@toefl.dev`;

// csrfToken extracts toefl_csrf from the login Set-Cookie header(s). k6
// sends cookies automatically on subsequent requests (VU-level jar), so we
// only need the value to echo back in the X-CSRF-Token header.
function csrfToken(loginRes) {
  const setCookie = loginRes.headers['Set-Cookie'] || '';
  const m = /toefl_csrf=([^;]+)/.exec(setCookie);
  if (!m) {
    fail(`no toefl_csrf in login Set-Cookie for ${EMAIL()}: ${setCookie}`);
  }
  return m[1];
}

function csrfHeader(token) {
  return { 'X-CSRF-Token': token, 'Content-Type': 'application/json' };
}

export const options = {
  scenarios: {
    quiz_flow: {
      executor: 'ramping-vus',
      startVUs: 0,
      stages: [
        { duration: '15s', target: 10 },
        { duration: '20s', target: 30 },
        { duration: '15s', target: 0 },
      ],
      gracefulStop: '10s',
    },
  },
  thresholds: {
    http_req_duration: ['p(95)<500', 'p(99)<1000'],
    http_req_failed:   ['rate<0.01'],
    checks:            ['rate>0.98'],
  },
};

export default function () {
  const login = http.post(
    `${API}/auth/login`,
    JSON.stringify({ email: EMAIL(), password: PASSWORD }),
    { headers: { 'Content-Type': 'application/json' } },
  );
  const loginOk = check(login, {
    'login 200': (r) => r.status === 200,
    'login role student': (r) => r.json('data.role') === 'student',
  });
  if (!loginOk) {
    fail(`login failed for ${EMAIL()}: ${login.status}`);
  }
  const token = csrfToken(login);

  const exams = http.get(`${API}/exams`);
  check(exams, { 'exams 200': (r) => r.status === 200 });

  const start = http.post(
    `${API}/attempts`,
    JSON.stringify({ exam_template_id: EXAM_ID, mode: 'per_question' }),
    { headers: csrfHeader(token) },
  );
  const startOk = check(start, { 'start 201': (r) => r.status === 201 });
  if (!startOk) {
    fail(`start failed for ${EMAIL()}: ${start.status} ${start.body}`);
  }

  const attemptID = start.json('data.attempt.id');
  const items = start.json('data.items') || [];
  for (const item of items) {
    const res = http.put(
      `${API}/attempts/${attemptID}/answers/${item.id}`,
      JSON.stringify({ chosen_index: 0, time_taken_ms: 1200 }),
      { headers: csrfHeader(token) },
    );
    check(res, { 'answer 204': (r) => r.status === 204 });
  }

  const submit = http.post(`${API}/attempts/${attemptID}/submit`, null, {
    headers: csrfHeader(token),
  });
  check(submit, {
    'submit 200': (r) => r.status === 200,
    'score is number': (r) => typeof r.json('data.report.score_pct') === 'number',
  });

  const review = http.get(`${API}/attempts/${attemptID}/review`);
  check(review, { 'review 200': (r) => r.status === 200 });

  const dashboard = http.get(`${API}/dashboard/stats`);
  check(dashboard, { 'dashboard 200': (r) => r.status === 200 });

  // Think time: real students pause between questions/actions.
  sleep(0.5);
}